package si.spindl.crm;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import si.spindl.identity.*;
import si.spindl.party.*;
import si.spindl.sales.SalesDtos;
import si.spindl.sales.SalesDtos.QuoteLineRequest;
import si.spindl.sales.SalesService;
import si.spindl.tenant.DevelopmentTenant;
import si.spindl.reports.LeadPipelineWorkflowService;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.util.*;

@Service
public class LeadService {
    private static final Set<String> STAGES=Set.of("NEW","QUALIFIED","PROPOSAL","WON","LOST");
    private static final Set<String> ACTIVITY_TYPES=Set.of("NOTE","CALL","EMAIL","MEETING","TASK");
    private final DevelopmentTenant tenant;private final LeadRepository leads;private final LeadActivityRepository activities;private final CustomerRepository customers;private final TenantMembershipRepository memberships;private final TenantAuditEventRepository audit;private final SalesService sales;private final TenantRolePermissionRepository permissions;private final TenantBranchRepository branches;private final TenantMembershipBranchRepository memberBranches;private final LeadPipelineWorkflowService leadWorkflow;
    public LeadService(DevelopmentTenant tenant,LeadRepository leads,LeadActivityRepository activities,CustomerRepository customers,TenantMembershipRepository memberships,TenantAuditEventRepository audit,SalesService sales,TenantRolePermissionRepository permissions,TenantBranchRepository branches,TenantMembershipBranchRepository memberBranches,LeadPipelineWorkflowService leadWorkflow){this.tenant=tenant;this.leads=leads;this.activities=activities;this.customers=customers;this.memberships=memberships;this.audit=audit;this.sales=sales;this.permissions=permissions;this.branches=branches;this.memberBranches=memberBranches;this.leadWorkflow=leadWorkflow;}

    @Transactional(readOnly=true) public List<LeadView> list(UUID actorId){UUID tenantId=tenant.currentTenantId();String role=memberships.findActiveRole(tenantId,actorId).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Workspace membership is inactive"));List<LeadEntity> rows;if(permissions.allows(tenantId,role,"crm","leads","view","ALL"))rows=leads.findAllByTenantIdOrderByUpdatedAtDesc(tenantId);else{java.util.LinkedHashMap<UUID,LeadEntity> visible=new java.util.LinkedHashMap<>();if(permissions.allows(tenantId,role,"crm","leads","view","OWN"))leads.findAllByTenantIdAndOwnerUserIdOrderByUpdatedAtDesc(tenantId,actorId).forEach(l->visible.put(l.getId(),l));if(permissions.allows(tenantId,role,"crm","leads","view","TEAM")){List<UUID> owners=new java.util.ArrayList<>();owners.add(actorId);memberships.findAllByTenantIdAndManagerUserIdAndActiveTrueOrderByCreatedAtAsc(tenantId,actorId).stream().map(TenantMembershipEntity::getUserId).forEach(owners::add);leads.findAllByTenantIdAndOwnerUserIdInOrderByUpdatedAtDesc(tenantId,owners).forEach(l->visible.put(l.getId(),l));}if(permissions.allows(tenantId,role,"crm","leads","view","BRANCH")){List<UUID> branchIds=memberBranches.findActiveBranchIds(tenantId,actorId);if(!branchIds.isEmpty())leads.findAllByTenantIdAndBranchIdInOrderByUpdatedAtDesc(tenantId,branchIds).forEach(l->visible.put(l.getId(),l));}rows=visible.values().stream().sorted(java.util.Comparator.comparing(LeadEntity::getUpdatedAt).reversed()).toList();}return rows.stream().map(l->view(tenantId,l)).toList();}
    @Transactional(readOnly=true) public LeadView get(UUID actorId,UUID id){UUID tenantId=tenant.currentTenantId();LeadEntity lead=find(tenantId,id);authorize(actorId,tenantId,lead,"view");return view(tenantId,lead);}

    @Transactional public LeadView create(UUID actorId,CreateLeadRequest request){UUID tenantId=tenant.currentTenantId();String email=normalize(request.email());String phone=normalize(request.phone());if(email==null&&phone==null)throw badRequest("Add an email address or phone number");String role=memberships.findActiveRole(tenantId,actorId).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Workspace membership is inactive"));boolean allScope=permissions.allows(tenantId,role,"crm","leads","create","ALL");boolean teamScope=permissions.allows(tenantId,role,"crm","leads","create","TEAM");boolean branchScope=permissions.allows(tenantId,role,"crm","leads","create","BRANCH");boolean ownScope=permissions.allows(tenantId,role,"crm","leads","create","OWN");UUID owner=request.ownerUserId()==null?actorId:request.ownerUserId();if(!allScope){if(teamScope){boolean inTeam=owner.equals(actorId)||memberships.findAllByTenantIdAndManagerUserIdAndActiveTrueOrderByCreatedAtAsc(tenantId,actorId).stream().anyMatch(m->m.getUserId().equals(owner));if(!inTeam)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Team-scope roles can only assign leads to themselves or a direct report");}else if(!owner.equals(actorId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This role can only assign leads to itself");}if(memberships.findActiveRole(tenantId,owner).isEmpty())throw badRequest("Lead owner must be an active workspace member");UUID branchId=request.branchId()==null?branches.findFirstByTenantIdAndDefaultBranchTrue(tenantId).map(TenantBranchEntity::getId).orElseThrow():branches.findByTenantIdAndId(tenantId,request.branchId()).filter(TenantBranchEntity::isActive).map(TenantBranchEntity::getId).orElseThrow(()->badRequest("Choose an active workspace branch"));if(!allScope&&branchScope&&!teamScope&&!ownScope&&!memberBranches.hasActiveAssignment(tenantId,actorId,branchId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You are not assigned to the selected branch");if(!allScope&&!teamScope&&!branchScope&&!ownScope)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Lead creation is not permitted");var lead=leads.save(new LeadEntity(tenantId,request.name().trim(),normalize(request.company()),email,phone,normalize(request.source()),owner,branchId,request.expectedValue(),normalize(request.nextActivityTitle()),request.nextActivityAt()));audit.save(new TenantAuditEventEntity(tenantId,actorId,"CRM_LEAD_CREATED","lead",lead.getId(),Map.of("stage","NEW")));return view(tenantId,lead);}

    @Transactional public LeadView stage(UUID actorId,UUID id,StageRequest request){UUID tenantId=tenant.currentTenantId();var lead=leads.findForUpdate(tenantId,id).orElseThrow(()->notFound("Lead not found"));authorize(actorId,tenantId,lead,"update");String stage=request.stage().trim().toUpperCase(Locale.ROOT);if(!leadWorkflow.supportsStage(tenantId,stage))throw badRequest("Choose a stage in the active lead workflow");if(stage.equals("WON")&&lead.getConvertedCustomerId()==null)throw conflict("Convert the lead to a customer before marking it won");if(lead.getConvertedCustomerId()!=null&&!stage.equals("WON"))throw conflict("A converted lead cannot leave the won stage");String prior=lead.getStage();String role=memberships.findActiveRole(tenantId,actorId).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Workspace membership is inactive"));leadWorkflow.requireTransition(tenantId,actorId,prior,stage,role);lead.moveTo(stage);audit.save(new TenantAuditEventEntity(tenantId,actorId,"CRM_LEAD_STAGE_CHANGED","lead",id,Map.of("previousStage",prior,"stage",stage)));return view(tenantId,lead);}

    @Transactional public LeadView addActivity(UUID actorId,UUID id,CreateActivityRequest request){UUID tenantId=tenant.currentTenantId();var lead=leads.findForUpdate(tenantId,id).orElseThrow(()->notFound("Lead not found"));authorize(actorId,tenantId,lead,"update");String type=request.activityType().trim().toUpperCase(Locale.ROOT);if(!ACTIVITY_TYPES.contains(type))throw badRequest("Activity type must be NOTE, CALL, EMAIL, MEETING, or TASK");String body=request.body().trim();var activity=activities.save(new LeadActivityEntity(tenantId,id,actorId,type,body,request.dueAt()));if(request.dueAt()!=null)lead.schedule(type.equals("TASK")?body:request.activityType(),request.dueAt());audit.save(new TenantAuditEventEntity(tenantId,actorId,"CRM_LEAD_ACTIVITY_ADDED","lead",id,Map.of("type",type)));return view(tenantId,lead);}

    @Transactional public LeadConversionView convert(UUID actorId,UUID id,ConvertLeadRequest request){UUID tenantId=tenant.currentTenantId();var lead=leads.findForUpdate(tenantId,id).orElseThrow(()->notFound("Lead not found"));authorize(actorId,tenantId,lead,"update");if(lead.getConvertedCustomerId()!=null)throw conflict("Lead has already been converted");if(lead.getStage().equals("LOST"))throw conflict("Reopen the lost lead before converting it");CustomerEntity customer=null;if(lead.getEmail()!=null&&!lead.getEmail().isBlank())customer=customers.findFirstByTenantIdAndEmailIgnoreCase(tenantId,lead.getEmail()).orElse(null);if(customer!=null&&!customer.isActive())throw conflict("The matching customer is inactive; reactivate it before converting this lead");boolean created=customer==null;if(created){String code="CRM-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT);String customerName=lead.getCompany()==null?lead.getName():lead.getCompany();customer=customers.save(new CustomerEntity(tenantId,code,customerName,lead.getEmail()==null?"":lead.getEmail(),"Active",actorId));}
        SalesDtos.QuoteView quote=null;if(request.quoteLines()!=null&&!request.quoteLines().isEmpty())quote=sales.createQuote(new SalesDtos.CreateQuoteRequest(customer.getId(),request.quoteValidUntil(),request.quoteNotes(),request.quoteLines()));lead.convert(customer.getId());audit.save(new TenantAuditEventEntity(tenantId,actorId,"CRM_LEAD_CONVERTED","lead",id,Map.of("customerId",customer.getId().toString(),"customerCreated",created,"quoteCreated",quote!=null)));return new LeadConversionView(id,customer.getId(),customer.getName(),created,quote==null?null:quote.id(),quote==null?null:quote.quoteNumber());}

    private void authorize(UUID actorId,UUID tenantId,LeadEntity lead,String action){String role=memberships.findActiveRole(tenantId,actorId).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Workspace membership is inactive"));if(permissions.allows(tenantId,role,"crm","leads",action,"ALL"))return;if(permissions.allows(tenantId,role,"crm","leads",action,"OWN")&&lead.getOwnerUserId().equals(actorId))return;if(permissions.allows(tenantId,role,"crm","leads",action,"TEAM")){if(lead.getOwnerUserId().equals(actorId)||memberships.findAllByTenantIdAndManagerUserIdAndActiveTrueOrderByCreatedAtAsc(tenantId,actorId).stream().anyMatch(member->member.getUserId().equals(lead.getOwnerUserId())))return;}if(permissions.allows(tenantId,role,"crm","leads",action,"BRANCH")&&memberBranches.hasActiveAssignment(tenantId,actorId,lead.getBranchId()))return;throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You do not have permission to access this lead");}

    private LeadView view(UUID tenantId,LeadEntity lead){var rows=activities.findAllByTenantIdAndLeadIdOrderByCreatedAtDesc(tenantId,lead.getId()).stream().map(a->new ActivityView(a.getId(),a.getActivityType(),a.getBody(),a.getDueAt(),a.getCompletedAt(),a.getCreatedAt(),a.getActorUserId())).toList();return new LeadView(lead.getId(),lead.getName(),lead.getCompany(),lead.getEmail(),lead.getPhone(),lead.getSource(),lead.getStage(),lead.getOwnerUserId(),lead.getBranchId(),lead.getExpectedValue(),lead.getNextActivityTitle(),lead.getNextActivityAt(),lead.getConvertedCustomerId(),lead.getCreatedAt(),lead.getUpdatedAt(),rows);}
    private LeadEntity find(UUID tenantId,UUID id){return leads.findByTenantIdAndId(tenantId,id).orElseThrow(()->notFound("Lead not found"));}
    private String normalize(String value){return value==null||value.isBlank()?null:value.trim();}
    private ResponseStatusException notFound(String message){return new ResponseStatusException(HttpStatus.NOT_FOUND,message);}private ResponseStatusException conflict(String message){return new ResponseStatusException(HttpStatus.CONFLICT,message);}private ResponseStatusException badRequest(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}

    public record CreateLeadRequest(@NotBlank @Size(max=180) String name,@Size(max=180) String company,@Email @Size(max=254) String email,@Size(max=40) String phone,@Size(max=80) String source,UUID ownerUserId,@DecimalMin("0.00") BigDecimal expectedValue,@Size(max=180) String nextActivityTitle,Instant nextActivityAt,UUID branchId){}
    public record StageRequest(@NotBlank String stage){}
    public record CreateActivityRequest(@NotBlank String activityType,@NotBlank @Size(max=2000) String body,@FutureOrPresent Instant dueAt){}
    public record ConvertLeadRequest(@FutureOrPresent LocalDate quoteValidUntil,@Size(max=1000) String quoteNotes,List<@Valid QuoteLineRequest> quoteLines){}
    public record ActivityView(UUID id,String activityType,String body,Instant dueAt,Instant completedAt,Instant createdAt,UUID actorUserId){}
    public record LeadView(UUID id,String name,String company,String email,String phone,String source,String stage,UUID ownerUserId,UUID branchId,BigDecimal expectedValue,String nextActivityTitle,Instant nextActivityAt,UUID convertedCustomerId,Instant createdAt,Instant updatedAt,List<ActivityView> activities){}
    public record LeadConversionView(UUID leadId,UUID customerId,String customerName,boolean customerCreated,UUID quoteId,String quoteNumber){}
}
